const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const bryceCanyonPoint = ee.Geometry.Point([-112.1827, 37.5930]); // Approximate center of Bryce Canyon National Park
  const lasVegasPoint = ee.Geometry.Point([-115.1373, 36.1716]); // Approximate center of Las Vegas
  const bufferDistance = 5000; // 5 km buffer for the regions of interest
  const bryceCanyonRegion = bryceCanyonPoint.buffer(bufferDistance);
  const lasVegasRegion = lasVegasPoint.buffer(bufferDistance);

  // The question asks for 2024, but annual VIIRS nighttime lights (VNL) composites
  // for 2024 are not yet available. The latest annual composite is typically for the previous
  // full year. We will use the latest available annual composite, which is 2022.
  const year = 2022;
  const startDate = ee.Date.fromYMD(year, 1, 1);
  const endDate = ee.Date.fromYMD(year, 12, 31);

  // 2. Data Acquisition & Check
  const vnlCollection = ee.ImageCollection('NOAA/VIIRS/DNB/ANNUAL_V20')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  if (vnlCollection.size().getInfo() === 0) {
    console.log(`No VIIRS Nighttime Lights data found for year ${year}.`);
    console.log('C1'); // Empty Collection
    return;
  }

  const vnlImage = vnlCollection.first();

  // Scale for reduceRegion. VNL resolution is ~750m, using 1000m scale is appropriate.
  const scale = 1000;

  // 3. Processing & Calculation
  const getMeanLightIntensity = async (region, name) => {
    // Check for valid pixels before reducing
    const countPixels = await vnlImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    if (countPixels === 0) {
      console.log(`No valid pixels found for ${name} after filtering/masking.`);
      return { value: null, pixels: 0 }; // Indicate no valid pixels
    }

    const meanIntensity = await vnlImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    return { value: meanIntensity, pixels: countPixels };
  };

  const bryceIntensityData = await getMeanLightIntensity(bryceCanyonRegion, 'Bryce Canyon');
  const lasVegasIntensityData = await getMeanLightIntensity(lasVegasRegion, 'Las Vegas');

  const bryceMean = bryceIntensityData.value;
  const lasVegasMean = lasVegasIntensityData.value;
  const brycePixels = bryceIntensityData.pixels;
  const lasVegasPixels = lasVegasIntensityData.pixels;

  // 4. Validation & Final Answer
  if (bryceMean === null || isNaN(bryceMean) || lasVegasMean === null || isNaN(lasVegasMean)) {
    console.log("Calculation resulted in null or NaN for one or both locations.");
    console.log('C3'); // Calculation Failure
    return;
  }

  if (brycePixels === 0 || lasVegasPixels === 0) {
    console.log("No valid pixels for one or both locations.");
    console.log('C2'); // No Valid Pixels
    return;
  }

  console.log(`Nighttime Light Intensity (avg_rad) for ${year}:`);
  console.log(`Bryce Canyon: ${bryceMean.toFixed(3)} nW/cm²/sr (Pixels: ${brycePixels})`);
  console.log(`Las Vegas: ${lasVegasMean.toFixed(3)} nW/cm²/sr (Pixels: ${lasVegasPixels})`);

  if (bryceMean < lasVegasMean) {
    console.log('A'); // Yes
  } else {
    console.log('B'); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
